def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    radii = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    total = sum(occ)
    overlap = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                overlap += occ[i] * occ[j] * max(0.0, 1.0 - d / (a + b)) ** 2
    return 0.5 * overlap / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    counts = {}
    for i in range(n):
        element = sites[i].get('element')
        counts[element] = counts.get(element, 0.0) + occ[i]
    occupied = sum(occ)
    nearest = [inf for x in sites]
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    same = 0.0
    total = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and nearest[i] < inf and d <= 1.35 * nearest[i]:
            w = occ[i] * occ[j]
            total += w
            if sites[i].get('element') == sites[j].get('element'):
                same += w
    if total <= 0 or occupied <= 0:
        return 0.0
    return same / total - sum((v / occupied) ** 2 for v in counts.values())

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    distances = [[] for x in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            if len(distances[i]) < 12 or d < distances[i][-1]:
                distances[i] = sorted(distances[i] + [d])[:12]
    total = 0.0
    value = 0.0
    for i in range(n):
        values = distances[i]
        if len(values) >= 2:
            gap = max(log(values[k + 1] / values[k]) for k in range(len(values) - 1))
            value += occ[i] * gap
            total += occ[i]
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    density = s.get('density_g_cm3')
    if density is not None and density > 0:
        return log1p(density)
    props = s.get('element_properties') or {}
    mass = 0.0
    occupied = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        occupied += o
        m = (props.get(site.get('element')) or {}).get('mass_amu')
        if m is not None and m > 0:
            mass += o * m
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        volume = v * occupied if v is not None and v > 0 else 0.0
    return log1p(1.66053906660 * mass / volume) if volume > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    network = []
    for site in sites:
        p = props.get(site.get('element')) or {}
        group = p.get('group')
        flag = p.get('Z') == 1 or (group is not None and 14 <= group <= 17)
        network = network + [flag]
    nearest = [inf for x in sites]
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    value = 0.0
    total = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and nearest[i] < inf and d <= 1.35 * nearest[i]:
            weight = occ[i] * occ[j]
            total += weight
            if network[i] and network[j]:
                value += weight
    return value / total if total > 0 else 0.0
